CREATE TABLE category (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE app_user (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_admin BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE product (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, description TEXT, price NUMERIC(10,2) NOT NULL CHECK (price >= 0), stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0), active BOOLEAN NOT NULL DEFAULT TRUE, image_url VARCHAR(300), category_id INTEGER NOT NULL REFERENCES category(id));
CREATE TABLE address (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES app_user(id), street VARCHAR(160) NOT NULL, number VARCHAR(20) NOT NULL, city VARCHAR(100) NOT NULL, state VARCHAR(2) NOT NULL, zip_code VARCHAR(12) NOT NULL);
CREATE TABLE orders (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES app_user(id), address_id INTEGER REFERENCES address(id), status VARCHAR(40) NOT NULL, total NUMERIC(10,2) NOT NULL CHECK (total >= 0), created_at TIMESTAMP NOT NULL);
CREATE TABLE order_item (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES product(id), quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0));
CREATE TABLE payment (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id), method VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, transaction_code VARCHAR(80) NOT NULL, paid_at TIMESTAMP NOT NULL);
CREATE INDEX idx_product_category ON product(category_id);
CREATE INDEX idx_order_user ON orders(user_id);
CREATE INDEX idx_order_item_order ON order_item(order_id);
